@startuml

class Airline {
  +id : string
}

class Flight {
  +id : string
  +departureTime : time
  +arrivalTime : time
}

class Airport {
  +id : string
}

class Aircraft {
  +state : string
}

class AircraftType {
}

class Pilot {
  +experienceLevel : int
}

class Captain extends Pilot {}

class CoPilot extends Pilot {}

class Navigator extends Pilot {}

Airline "1" -- "*" Flight : operates
Airline "1" -- "*" Aircraft : owns
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives to
Flight "*" -- "1" Aircraft : uses
Flight "1" -- "1" Captain : has
Flight "1" -- "1" CoPilot : has
Aircraft "*" -- "1" AircraftType : is of
AircraftType "1" -- "1..*" Captain : requires
AircraftType "1" -- "1..*" CoPilot : requires
AircraftType "1" -- "0..*" Navigator : requires

@enduml

